#!/bin/sh
# The staging root (ROOT of SGI's build): IRIX headers and the IRIX libraries built so far; commands install here
# too.  Compiles see its usr/include AFTER the host's headers (irixcc.py turns -I$ROOT/usr/include into -idirafter),
# so the host wins for common headers and the IRIX-only ones (pfmt.h, sys/euc.h, msgs/...) are still found.
#   usr/include         the installed IRIX development headers (holyshit), then the kernel's sys/ headers from the
#                       source tree where those lack one, minus every header the host also has; msgs/ is generated by eoe/cmd/messages (build-eoe.py)
#   usr/include/make    the tool root's make rules
# Paths literal.
set -e
R=/home/nekron/opt/claude-work/eoe/root
mkdir -p $R/usr/include $R/usr/lib32 $R/usr/lib64 $R/usr/lib
cp -a /home/nekron/Projects/irix-work/holyshit/usr/include/. $R/usr/include/
cp -n /home/nekron/Projects/irix-657m-src/irix/kern/sys/*.h $R/usr/include/sys/ 2>/dev/null || true
# only the IRIX-only headers stay: where the host has a header of the same name, its version is used everywhere,
# also when an IRIX header includes it with quotes
rm -f $R/usr/include/sys/procset.h      # the host has idtype_t in <sys/wait.h>; compat/include/sys/procset.h
(cd $R/usr/include && find . -name '*.h' | while read -r f; do if [ -e "/usr/include/$f" ]; then rm -f "$f"; fi; done)
rm -rf $R/usr/include/make
cp -a /home/nekron/Projects/irix-work/userland/toolroot/usr/include/make $R/usr/include/make
echo "root ready: $(find $R/usr/include -name '*.h' | wc -l) headers"
